using CUE4Parse.FileProvider;using CUE4Parse.UE4.Assets.Exports.StaticMesh;using CUE4Parse.UE4.Assets.Exports.Material;using CUE4Parse.UE4.Assets.Exports.Texture;using CUE4Parse_Conversion.Meshes;using CUE4Parse_Conversion.Textures;using Newtonsoft.Json;using System.Text.Json;using System.Text.RegularExpressions;
static class Rails { public static void Run(DefaultFileProvider provider,string output){var root=Path.GetFullPath(Path.Combine(output,"../rail-native"));Directory.CreateDirectory(Path.Combine(root,"textures"));using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"resolved-rail-sockets.json")));var requests=new HashSet<string>();foreach(var actor in doc.RootElement.EnumerateArray())foreach(var c in actor.GetProperty("connectorTemplate").GetProperty("Properties").GetProperty("MeshConfigs").EnumerateArray()){if(c.GetProperty("bCollisionOnly").GetBoolean())continue;foreach(var m in c.GetProperty("Meshes").EnumerateArray())if(m.ValueKind==JsonValueKind.Object)requests.Add(m.GetProperty("ObjectPath").GetString()!.Split('.')[0]+".uasset");if(c.GetProperty("Mesh").ValueKind==JsonValueKind.Object)requests.Add(c.GetProperty("Mesh").GetProperty("ObjectPath").GetString()!.Split('.')[0]+".uasset");}
var results=new List<object>();var materials=new Dictionary<string,object>();var errors=new List<string>();
foreach(var source in requests)try{var mesh=provider.LoadPackage(source).GetExports().OfType<UStaticMesh>().First();if(!mesh.TryConvert(null,out var converted)||converted.LODs.Count==0)throw new Exception("No geometry");var lod=converted.LODs[0];var name=mesh.Name;using(var w=new BinaryWriter(File.Create(Path.Combine(root,name+".vertices.bin"))))foreach(var v in lod.Verts){w.Write(v.Position.X);w.Write(v.Position.Y);w.Write(v.Position.Z);w.Write(v.Normal.X);w.Write(v.Normal.Y);w.Write(v.Normal.Z);w.Write(v.UV.U);w.Write(v.UV.V);}using(var w=new BinaryWriter(File.Create(Path.Combine(root,name+".indices.bin"))))foreach(var i in lod.Indices.Value)w.Write(i);var sections=new List<object>();foreach(var s in lod.Sections.Value){var m=s.Material?.Load<UMaterialInterface>();var key=m?.GetPathName()??"default";sections.Add(new{material=key,start=s.FirstIndex,count=s.NumFaces*3});if(materials.ContainsKey(key))continue;var p=new CMaterialParams2();m?.GetParams(p,EMaterialFormat.AllLayers);UTexture? color=null,normal=null,rough=null;p.TryGetTexture2d(out color,CMaterialParams2.Diffuse[0]);p.TryGetTexture2d(out normal,CMaterialParams2.Normals[0]);rough=p.Textures.FirstOrDefault(k=>Regex.IsMatch(k.Key,"rough|specular",RegexOptions.IgnoreCase)).Value as UTexture;string? Save(UTexture? tex){if(tex==null)return null;var file="textures/"+tex.Name+".png";if(!File.Exists(Path.Combine(root,file))){var pixels=tex.Decode()??throw new Exception("No pixels");File.WriteAllBytes(Path.Combine(root,file),pixels.Encode(ETextureFormat.Png,false,out _));}return file;}materials[key]=new{file=Save(color),normalFile=Save(normal),packedFile=Save(rough),scalars=p.Scalars,colors=p.Colors,textures=p.Textures.ToDictionary(x=>x.Key,x=>x.Value?.GetPathName())};}results.Add(new{name,source,vertices=lod.Verts.Length,indices=lod.Indices.Value.Length,sections,min=new[]{mesh.RenderData.Bounds.Origin.X-mesh.RenderData.Bounds.BoxExtent.X,mesh.RenderData.Bounds.Origin.Y-mesh.RenderData.Bounds.BoxExtent.Y,mesh.RenderData.Bounds.Origin.Z-mesh.RenderData.Bounds.BoxExtent.Z},max=new[]{mesh.RenderData.Bounds.Origin.X+mesh.RenderData.Bounds.BoxExtent.X,mesh.RenderData.Bounds.Origin.Y+mesh.RenderData.Bounds.BoxExtent.Y,mesh.RenderData.Bounds.Origin.Z+mesh.RenderData.Bounds.BoxExtent.Z}});converted.Dispose();Console.WriteLine(name);}catch(Exception e){errors.Add(source+": "+e.Message);}
File.WriteAllText(Path.Combine(root,"meshes.json"),JsonConvert.SerializeObject(new{meshes=results,materials,errors},Formatting.Indented));Console.WriteLine($"Rail meshes {results.Count}; materials {materials.Count}; errors {errors.Count}");}}
